#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3B step 7: ML-DSA-65 KeyGen
#
# This closes ML-DSA. KeyGen was missing: Sign and Verify were built first and
# the gap only surfaced while taking inventory for Layer 4, which is a better
# place to find it than inside an integrated core.
#
# BOTH KEY HALVES ARE COMPARED. pk is a function of t1 alone, so a defect
# confined to s1, s2 or t0 leaves pk bit-identical while corrupting sk -- and
# those three are exactly what Sign consumes. Mutation M6 was validated
# against the model as producing an IDENTICAL public key; it is killed by the
# secret key comparison and by nothing else. The same distinction showed up
# during bring-up, where pk passed all 1952 bytes while sk failed at byte 128
# exactly, which is where the packed s1 begins.
#
# THE DEFECT WORTH RECORDING is how the third one was found. The observed
# s1_hat matched no transform of s1 at all: not the forward NTT, not the
# lifted version, not a double transform, not a shifted copy. Several rounds
# went into testing transform variants before the obvious conclusion, that
# when a result matches no plausible variant of the operation, the operation
# is fine and the INPUT is wrong. Halting after the copy and before the NTT
# showed the destination was zero except for its last coefficient: cnt had
# not been reset and the copy started at index 63.
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line:
#   PQC L3B DSAKG PASS cases=8 sig=af470b97689ada71
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/dsa_sign.vhd rtl/dsa_verify.vhd rtl/codec_d.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/dsa_keygen.vhd" << 'B64EOF'
LS0gPT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09
PT09PT09PT09PT09PT09PT09PT09PT0KLS0gSEVSQ09TU05VWCBQUUMgSVAgQ29yZSAtIExheWVy
