  chmod +x "$DEST/verif/mutate_dsakg.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/keccak_pkg.vhd ../rtl/keccak_f1600.vhd \
       ../rtl/keccak_sponge.vhd ../rtl/ntt_d_tables_pkg.vhd \
       ../rtl/pqc_round_d_pkg.vhd ../rtl/poly_mem_d.vhd \
       ../rtl/byte_mem_d.vhd ../rtl/ntt_d_unit.vhd ../rtl/sampler_d.vhd \
       ../rtl/codec_d.vhd ../rtl/dsa_keygen.vhd ../rtl/dsa_keygen_top.vhd \
       tb_dsa_keygen.vhd

  ghdl -e --std=08 tb_dsa_keygen > /dev/null 2>&1
  echo "--- KeyGen checkpoints (seconds each) ---"
  for st in 1 2 3 4; do
    ghdl -r --std=08 tb_dsa_keygen -gG_STAGE=$st --stop-time=40000ms 2>&1 \
      | grep "CHECKPOINT PASS" | sed 's/.*(report note): //'
  done

  echo "--- KeyGen, eight ACVP vectors, pk and sk both compared ---"
  ghdl -r --std=08 tb_dsa_keygen -gG_STAGE=0 --stop-time=400000ms 2>&1 \
    | grep "DSAKG PASS" | sed 's/.*(report note): //'
)
